import org.apache.commons.lang3.time.*;
import java.text.*;
import java.util.*;

public class Probe {
    public static void main(String[] args) throws Exception {
        TimeZone tz = TimeZone.getTimeZone("America/Los_Angeles");
        Locale locale = Locale.US;

        // 1. error index test
        FastDateParser fdf = new FastDateParser("yyyy-MM-dd", tz, locale);
        ParsePosition pos = new ParsePosition(0);
        Date d = fdf.parse("20xx-01-01", pos);
        System.out.println("test1 date=" + d + " errIdx=" + pos.getErrorIndex() + " idx=" + pos.getIndex());

        // 2. partial consumption
        FastDateParser fdf2 = new FastDateParser("yyyy", tz, locale);
        ParsePosition pos2 = new ParsePosition(0);
        Date d2 = fdf2.parse("1999extra", pos2);
        System.out.println("test2 date=" + d2 + " idx=" + pos2.getIndex());

        // 3. out of bounds pos
        ParsePosition pos3 = new ParsePosition(100);
        Date d3 = fdf2.parse("1999", pos3);
        System.out.println("test3 date=" + d3 + " errIdx=" + pos3.getErrorIndex());

        // 4. GMT+02:00 zone parse
        FastDateParser fdfz = new FastDateParser("z", tz, locale);
        ParsePosition posz = new ParsePosition(0);
        Calendar cal = Calendar.getInstance(tz, locale);
        cal.clear();
        boolean ok = fdfz.parse("GMT+02:00", posz, cal);
        System.out.println("test4 ok=" + ok + " zoneOffset=" + cal.get(Calendar.ZONE_OFFSET) + " errIdx=" + posz.getErrorIndex());

        // 5. overflow digits
        FastDateParser fdfy = new FastDateParser("yyyy", tz, locale);
        try {
            Date dy = fdfy.parse("99999999999999");
            System.out.println("test5 date=" + dy);
        } catch (ParseException e) {
            System.out.println("test5 ParseException: " + e.getMessage());
        }

        // 6. unsupported pattern letter
        try {
            FastDateParser bad = new FastDateParser("Q", tz, locale);
            System.out.println("test6 no exception, pattern=" + bad.getPattern());
        } catch (IllegalArgumentException e) {
            System.out.println("test6 IAE: " + e.getMessage());
        }

        // 7. unterminated quote
        try {
            FastDateParser bad2 = new FastDateParser("yyyy'bad", tz, locale);
            System.out.println("test7 no exception");
        } catch (IllegalArgumentException e) {
            System.out.println("test7 IAE: " + e.getMessage());
        }

        // 8. non-lenient calendar overflow
        FastDateParser fdfmd = new FastDateParser("MM/dd/yyyy", tz, locale);
        Calendar nlCal = Calendar.getInstance(tz, locale);
        nlCal.clear();
        nlCal.setLenient(false);
        ParsePosition posmd = new ParsePosition(0);
        boolean okmd = fdfmd.parse("02/30/2021", posmd, nlCal);
        System.out.println("test8 parseOk=" + okmd);
        try {
            Date dmd = nlCal.getTime();
            System.out.println("test8 getTime succeeded: " + dmd);
        } catch (IllegalArgumentException e) {
            System.out.println("test8 IAE on getTime: " + e.getMessage());
        }

        // 9. two digit year boundary
        Calendar c2 = Calendar.getInstance(tz, locale);
        c2.clear();
        c2.set(1950, Calendar.JANUARY, 1);
        Date centuryStart = c2.getTime();
        FastDateParser fdfyy = new FastDateParser("yy", tz, locale, centuryStart);
        Date r49 = fdfyy.parse("49");
        Date r50 = fdfyy.parse("50");
        Calendar check = Calendar.getInstance(tz, locale);
        check.setTime(r49);
        System.out.println("test9 year49=" + check.get(Calendar.YEAR));
        check.setTime(r50);
        System.out.println("test9 year50=" + check.get(Calendar.YEAR));

        // 10. case insensitive month
        FastDateParser fdfm = new FastDateParser("MMM", tz, locale);
        Calendar cm = Calendar.getInstance(tz, locale);
        cm.clear();
        boolean okm = fdfm.parse("JAN", new ParsePosition(0), cm);
        System.out.println("test10 ok=" + okm + " month=" + cm.get(Calendar.MONTH));

        // 11. toString content
        System.out.println("test11 toString=" + fdf.toString());

        // 12. equals ignoring centuryStart
        FastDateParser a = new FastDateParser("yyyy-MM-dd", tz, locale, new Date(0));
        FastDateParser b = new FastDateParser("yyyy-MM-dd", tz, locale, new Date(1000000000L));
        System.out.println("test12 equals=" + a.equals(b) + " hashEq=" + (a.hashCode()==b.hashCode()));

        // 13. getTimeZone defensive copy
        FastDateParser fdftz = new FastDateParser("yyyy", tz, locale);
        TimeZone got = fdftz.getTimeZone();
        got.setRawOffset(123456);
        TimeZone got2 = fdftz.getTimeZone();
        System.out.println("test13 rawOffsetAfterMutation=" + got2.getRawOffset() + " original=" + tz.getRawOffset());
    }
}
EOF
javac -cp target/classes -d $TMPDIR/scratch $TMPDIR/scratch/Probe.java && java -cp target/classes:$TMPDIR/scratch Probe

